 \left(|q^{e_{L} \mu_{L}}_{\rm{SM}}|^{2}-|q^{e_{R} \mu_{R}}|^{2}\right)
 +(1-\cos\theta)^2
 \left(|q^{e_{L} \mu_{R}}_{\rm{SM}}|^{2}-|q^{e_{R} \mu_{L}}_{\rm{SM}}|^{2}\right)
}
{(1+\cos\theta)^2
 \left(|q^{e_{L} \mu_{L}}_{\rm{SM}}|^{2}+|q^{e_{R} \mu_{R}}|^{2}\right)
 +(1-\cos\theta)^2
 \left(|q^{e_{L} \mu_{R}}_{\rm{SM}}|^{2}+|q^{e_{R} \mu_{L}}_{\rm{SM}}|^{2}\right)
 } \, ,   \label{ALR-d-no-mf-2a}  \\
 {\cal A}_{\rm LR}(\cos\theta)^{x_H=-1}
 & \ \simeq \ \frac{(1+\cos\theta)^2
 \left(|q^{e_{L} \mu_{L}}|^{2}-|q^{e_{R} \mu_{R}}_{\rm{SM}}|^{2}\right)
 +(1-\cos\theta)^2
 \left(|q^{e_{L} \mu_{R}}_{\rm{SM}}|^{2}-|q^{e_{R} \mu_{L}}_{\rm{SM}}|^{2}\right)
}
{(1+\cos\theta)^2
 \left(|q^{e_{L} \mu_{L}}|^{2}+|q^{e_{R} \mu_{R}}_{\rm{SM}}|^{2}\right)
 +(1-\cos\theta)^2
 \left(|q^{e_{L} \mu_{R}}_{\rm{SM}}|^{2}+|q^{e_{R} \mu_{L}}_{\rm{SM}}|^{2}\right)
 }.
 \label{ALR-d-no-mf-2} 
\end{align}

The results are shown in the top panels of Fig~\ref{ALRtheta-2}. 

For the $b\overline{b}$ process we find the BSM contributions for different $x_H$ in the differential LR asymmetry in terms of $q^{\rm{XY}}$ following Table~\ref{tabASM}. Using Eq.~\ref{A_LR-cos-obs}, the differential LR asymmetry of this process for $x_H=-1$ and $1$ can be written as 
\begin{align}
{\cal A}_{\rm LR}(\cos\theta)^{x_H=-1}
 & \ \simeq \ \frac{(1+\cos\theta)^2
 \left(|q^{e_{L} b_{L}}|^{2}-|q^{e_{R} b_{R}}_{\rm{SM}}|^{2}\right)
 +(1-\cos\theta)^2
 \left(|q^{e_{L} b_{R}}|^{2}-|q^{e_{R} b_{L}}_{\rm{SM}}|^{2}\right)
}
{(1+\cos\theta)^2
 \left(|q^{e_{L} b_{L}}|^{2}+|q^{e_{R} b_{R}}_{\rm{SM}}|^{2}\right)
 +(1-\cos\theta)^2
 \left(|q^{e_{L} b_{R}}|^{2}+|q^{e_{R} b_{L}}_{\rm{SM}}|^{2}\right)
 } \, , \\
 {\cal A}_{\rm LR}(\cos\theta)^{x_H=1}
 & \ \simeq \ \frac{(1+\cos\theta)^2
 \left(|q^{e_{L} b_{L}}|^{2}-|q^{e_{R} b_{R}}_{\rm{SM}}|^{2}\right)
 +(1-\cos\theta)^2
 \left(|q^{e_{L} b_{R}}_{\rm{SM}}|^{2}-|q^{e_{R} b_{L}}|^{2}\right)
}
{(1+\cos\theta)^2
 \left(|q^{e_{L} b_{L}}|^{2}+|q^{e_{R} b_{R}}_{\rm{SM}}|^{2}\right)
 +(1-\cos\theta)^2
 \left(|q^{e_{L} b_{R}}_{\rm{SM}}|^{2}+|q^{e_{R} b_{L}}|^{2}\right)
 } \, . 
\label{ALR-d-no-mf-3} 
\end{align}

The results are shown in the middle panels of Fig~\ref{ALRtheta-2}. Similarly, we study the LR asymmetry for $e^-e^+ \to t \overline{t}$ process according to Table~\ref{tabASM} and Eq.~\ref{A_LR-cos-obs} for different $x_H$. 

We find that for all three final states, the size of the differential LR asymmetry increases with the increase in $\sqrt{s}$ from the SM prediction (solid black line). In the $U(1)_X$ case, it is governed by different couplings of the left and right-handed fermions with $Z^\prime$, as summarized in Table~\ref{tabASM}.




The amount of deviation from the SM in the differential asymmetries can be defined as
\begin{align}
\Delta_{\mathcal{A}_{\rm LR}}(\cos\theta) & \ = \ 
\frac{\mathcal{A}_{\rm LR}^{U(1)_X}(\cos\theta)}{\mathcal{A}_{\rm LR}^{\rm SM}(\cos\theta)}-1 \, .
\label{DeltaALRcos}
\end{align}
We show these deviations using $M_{Z^\prime}=7.5$ TeV in Fig.~\ref{DevALRtheta-2} for $\mu^+\mu^-$ (top panel), $b \overline{b}$ (middle panel) and $t \overline{t}$ (bottom panel) as a function of $\cos\theta$. We use $\sqrt{s}=250$ GeV (except $t \overline{t}$), $500$ GeV, $1$ TeV and $3$ TeV and present the results for $x_H=-2$, $-1$, $1$ and $2$. The theoretically estimated statistical error, shown as the gray-shaded band is estimated from
\begin{align}
 \Delta \mathcal{A}^{\rm stat}_{\rm LR} \ = \ 






 \frac{2\sqrt{N_{\rm LR}N_{\rm RL}}}
 {(N_{\rm LR}+N_{\rm RL})
 \left(\sqrt{N_{\rm LR}}-\sqrt{N_{\rm RL}}\right)}
{\cal A}_{\rm LR} \, , 
\label{Eq:Error-A_LR-1-1}
\end{align}
where $N_{\rm LR}=\mathcal{L}_{\rm int} \, \sigma_{\rm LR}$ and $N_{\rm RL}=\mathcal{L}_{\rm int} \, \sigma_{\rm RL}$.

From Fig.~\ref{DevALRtheta-2}, we find that the deviation in differential LR asymmetry for $e^-e^+ \to \mu^+ \mu^-$ process for $x_H=-2$ is slightly above the theoretically estimated statistical error for $\cos\theta > 0.37$; however, for $x_H=-1$ it is within the range of the statistical error. For $x_H=1$ and $2$, the deviations vary between $5\%-3\%$ and $10\%-8\%$ respectively for $-1 \leq \cos\theta \leq 1$. The deviations increase with $\sqrt{s}$. The differential LR asymmetry is negative for $x_H=2$ at $\sqrt{s}=3$ TeV which is reflected in the deviation of the differential LR asymmetry as well.


