\subsection{Left-right forward-backward asymmetry $(\mathcal{A}_{\rm{LR, FB}})$}

The left-right forward-backward (LR, FB) asymmetry $(\mathcal{A}_{\rm LR, FB})$~\cite{Blondel:1987gp,Abe:1994bj,Abe:1994bm,Abe:1995yh} can be defined as 
\begin{align}
\mathcal{A}_{\rm LR,FB}(\cos\theta)& \ = \ 
\frac{\left[\sigma_{\rm LR}(\cos\theta)
- \sigma_{\rm RL}(\cos\theta)\right]
- \left[\sigma_{\rm LR}(-\cos\theta)
- \sigma_{\rm RL}(-\cos\theta)\right]
}{
\left[\sigma_{\rm LR}(\cos\theta)
+ \sigma_{\rm RL}(\cos\theta)\right]
+ \left[\sigma_{\rm LR}(-\cos\theta)
+ \sigma_{\rm RL}(-\cos\theta)\right]} ~.
\label{ALRFB1}
\end{align}
In terms of the gauge interactions of the fermions, we write  $\mathcal{A}_{\rm LR,FB}$ as
\begin{align}
\mathcal{A}_{\rm LR,FB}(\cos\theta) 

 \ = \ & \frac{ 2\beta \cos\theta \big\{ \big( |q^{e_{L} f_{L}}|^{2} + |q^{e_{R} f_{L}}|^{2} \big) 
          - \big(  |q^{e_{L} f_{R}}|^{2} + |q^{e_{R} f_{R}}|^{2} \big) \big\}} 
{ \splitfrac{(1+\beta^{2}\cos^{2}\theta) \big\{ \big( |q^{e_{L} f_{L}}|^{2} + |q^{e_{R} f_{L}}|^{2} \big) 
          + \big(  |q^{e_{L} f_{R}}|^{2} + |q^{e_{R} f_{R}}|^{2} \big)\big\} }{+ 8\frac{m_{f}^{2}}{s} \big[ {\rm Re}(q^{e_{L} f_{L}} {q^{e_{L} f_{R}}}^{*})
  +{\rm Re}(q^{e_{R} f_{R}} {q^{e_{R} f_{L}}}^{*}) \big]}} \, . 

\label{ALRFB-x}
\end{align}
For $m_f \ll \sqrt{s}$ the differential LR-FB asymmetry can be written as
\begin{align}
\mathcal{A}_{\rm LR,FB}(\cos\theta)& \ \simeq \ 
 \Big[\frac{2 \cos\theta}{1+\cos^2\theta} \Big] \frac{\big( |q^{e_{L} f_{L}}|^{2} + |q^{e_{R} f_{L}}|^{2} \big) 
          - \big(  |q^{e_{L} f_{R}}|^{2} + |q^{e_{R} f_{R}}|^{2} \big)}{\big( |q^{e_{L} f_{L}}|^{2} + |q^{e_{R} f_{L}}|^{2} \big) 
          + \big(  |q^{e_{L} f_{R}}|^{2} + |q^{e_{R} f_{R}}|^{2} \big)} \, .
\label{ALRFB-mf0-11-1}
\end{align}
The observable LR-FB asymmetry can be written as
\begin{align}
&\mathcal{A}_{\rm LR,FB}(P_{e^-},P_{e^+},\cos\theta) \ = \ \frac{\splitfrac{\big[  \sigma(P_{e^-},P_{e^+},\cos\theta) + \sigma(-P_{e^-},-P_{e^+},-\cos\theta) \big]}{-\big[ \sigma(-P_{e^-},-P_{e^+},\cos\theta) +\sigma(P_{e^-},P_{e^+},-\cos\theta) \big] } }{\splitfrac{\big[\sigma(P_{e^-},P_{e^+},\cos\theta) + \sigma(-P_{e^-},-P_{e^+},-\cos\theta) \big]}{+\big[ \sigma(-P_{e^-},-P_{e^+},\cos\theta) +\sigma(P_{e^-},P_{e^+},-\cos\theta) \big]}},
\label{ALRFBcos-obs}
\end{align}
for $P_{e^-}<0$ and $|P_{e^-}|>|P_{e^+}|$. The relation between $\mathcal{A}_{\rm LR,FB}(\cos\theta)$ in Eq.~\ref{ALRFB1} and $\mathcal{A}_{\rm LR,FB}(P_{e^-},P_{e^+},\cos\theta)$ in Eq.~\ref{ALRFBcos-obs} is given by
\begin{align}
\mathcal{A}_{\rm LR,FB}(\cos\theta) \ = \ \frac{1}{P_{\rm eff}}
\mathcal{A}_{\rm LR,FB}(P_{e^-},P_{e^+},\cos\theta) ~. 
\end{align}








