\subsection{Differential and integrated cross sections}

The differential scattering cross section from Eq.~\ref{Xsec:dif} can be written as 
\bea
\frac{d\sigma}{d\cos\theta} \ = \ \frac{d\sigma^s}{d\cos\theta}+ \frac{d\sigma^t}{d\cos\theta}+ \frac{d\sigma^{st}}{d\cos\theta} \, , 
\label{Xsec-3}
\eea
where the three terms correspond to the $s$-channel, $t$-channel and interference between them, respectively. Explicitly, 
\bea
\frac{d\sigma^s}{d\cos\theta} & \ = \ & \frac{1}{32\pi s}\Big[ (1+P_{e^-}) (1-P_{e^+}) \Big\{u^2 |q_s(s)^{\rm{RR}}|^2+ t^2 |q_s(s)^{\rm{LR}}|^2\Big\} \nonumber \\
&& \quad + (1-P_{e^-}) (1+P_{e^+}) \Big\{u^2 |q_s(s)^{\rm{LL}}|^2+ t^2 |q_s(s)^{\rm{LR}}|^2\Big\}\Big] \, , \\
\frac{d\sigma^t}{d\cos\theta} & \ = \ & \frac{1}{32\pi s}\Big[ (1-P_{e^-}) (1+P_{e^+}) u^2 |q_t(s, \theta)^{\rm{LL}}|^2 +  (1+P_{e^-}) (1-P_{e^+}) u^2 |q_t(s, \theta)^{\rm{RR}}|^2  \nonumber \\
&& \quad + (1-P_{e^-}) (1-P_{e^+}) s^2 |q_t(s, \theta)^{\rm{LR}}|^2+ (1+P_{e^-}) (1+P_{e^+}) s^2 |q_t(s, \theta)^{\rm{LR}}|^2 \Big] \, , \\
\frac{d\sigma^{st}}{d\cos\theta}& \ = \ & \frac{1}{16\pi s} u^2 \Big[(1-P_{e^-}) (1+P_{e^+}) {\rm Re}(q_s(s)^{\rm{LL}} q_t^\ast(s, \theta)^{\rm{LL}})\nonumber \\
&& \quad +(1+P_{e^-}) (1-P_{e^+}) {\rm Re}(q_s(s)^{\rm{RR}} q_t^\ast(s, \theta)^{\rm{RR}})\Big] \, .
\eea
The deviation from the SM for the differential and integrated scattering cross sections can respectively be written as 
\bea
\Delta_{d\sigma} (P_{e^-}, P_{e^+}, \cos\theta) \ = \ \frac{\frac{d\sigma^{U(1)_X}}{d\cos\theta}}{\frac{d\sigma^{\rm{SM}}}{d\cos\theta}}-1\, , \,\,\,\,




\Delta_{\sigma} (P_{e^-}, P_{e^+}) \ = \ \frac{\sigma^{\rm{U(1)_X}}}{\sigma^{\rm{SM}}}-1 \, .
\label{dev-1}
\eea 
The estimated statistical error can theoretically be calculated as 
\bea
\Delta\sigma (P_{e^-}, P_{e^+}, -\cos\theta_{\rm{min}}, +\cos\theta_{\rm{max}}) \ = \ \frac{\sigma}{\sqrt{\mathcal{L}_{\rm{int}} \sigma}} \, .
\label{stsig}
\eea


