\subsection{Differential and integrated LR asymmetries}

The $e^-e^+ \to e^-e^+$ process contains $t$-channel scattering; hence the forward scattering dominates. Therefore the FB asymmetry $\mathcal{A}_{\rm{FB}}$ is not a well-measured quantity for Bhabha scattering. On the other hand, the LR asymmetry can be measured when the initial electron and /or positron is longitudinally polarized. 

The LR asymmetry of the differential cross section for $1 \ge P_- \ge 0$ and $1 \ge P_+ \ge -1$ can be written as 
\bea
&& \mathcal{A}_{\rm{LR}} (P_{-}, P_{+}, \cos\theta)  \ = \ \frac{\frac{d\sigma}{d\cos\theta} (P_{e^-}=-P_{-}, P_{e^+}=-P_{+})- \frac{d\sigma}{d\cos\theta} (P_{e^-}=+P_{-}, P_{e^+}=+P_{+})}{\frac{d\sigma}{d\cos\theta} (P_{e^-}=-P_{-}, P_{e^+}=-P_{+})+ \frac{d\sigma}{d\cos\theta} (P_{e^-}=+P_{-}, P_{e^+}=+P_{+})} \nonumber \\
&& \qquad  \ = \  \frac{(P_{-}-P_{+})\Big(\frac{d\sigma_{e_L^- e_R^+}}{d\cos\theta}-\frac{d\sigma_{e_R^- e_L^+}}{d\cos\theta}\Big)}{(1+P_{-} P_{+}) \Big(\frac{d\sigma_{e_L^- e_L^+}}{d\cos\theta}+\frac{d\sigma_{e_R^- e_R^+}}{d\cos\theta}\Big)+(1-P_{-} P_{+}) \Big(\frac{d\sigma_{e_L^- e_R^+}}{d\cos\theta}+\frac{d\sigma_{e_R^- e_L^+}}{d\cos\theta}\Big)} \nonumber \\
&& \qquad  \ = \   \frac{(P_{-}-P_{+})\Big\{u^2\Big(|q_{s}(s)^{\rm{LL}}+q_{t}(s, \theta)^{\rm{LL}}|^2- |q_{s}(s)^{\rm{RR}}+q_{t}(s, \theta)^{\rm{RR}}|^2\Big)\Big\}}{\splitfrac{(1+P_{-} P_{+})\Big(2 s^2 |q_{t}(s, \cos\theta)^{\rm{LR}}|^2\Big) + (1-P_{-} P_{+})}{
\Big\{u^2\Big(|q_{s}(s)^{\rm{LL}}+q_{t}(s, \theta)^{\rm{LL}}|^2+|q_{s}(s)^{\rm{RR}}+q_{t}(s, \theta)^{\rm{RR}}|^2\Big)+2t^2 |q_s(s)^{\rm{LR}}|^2\Big\}}} \, .
\label{ALR-d}
\eea






The LR asymmetry will vanish if both the initial states are unpolarized. 


The integrated LR asymmetry of the polarized cross sections can be given as 
\bea
\mathcal{A}_{\rm{LR}} (P_{-}, P_{+}) & \ = \ & \frac{\sigma(P_{e^-}=-P_{-}, P_{e^+}=-P_{+})- \sigma(P_{e^-}=+P_{-}, P_{e^+}=+P_{+})}{\sigma(P_{e^-}=-P_{-}, P_{e^+}=-P_{+})+ \sigma(P_{e^-}=+P_{-}, P_{e^+}=+P_{+})} \nonumber \\
& \ = \ & \frac{(P_{-}+P_{+})(\sigma_{e_L^- e_L^+}- \sigma_{e_R^- e_R^+})+(P_{-}-P_{+}) (\sigma_{e_L^- e_R^+}- \sigma_{e_R^- e_L^+})}{(1+P_{-}P_{+})(\sigma_{e_L^- e_L^+}+ \sigma_{e_R^- e_R^+})+(1-P_{-}P_{+}) (\sigma_{e_L^- e_R^+}+ \sigma_{e_R^- e_L^+})} \nonumber \\
& \ = \ & (P_{-}-P_{+}) \frac{\sigma_{e_L^- e_R^+}- \sigma_{e_R^- e_L^+}}{(1+P_{-}P_{+})(\sigma_{e_L^- e_L^+}+ \sigma_{e_R^- e_R^+})+(1-P_{-}P_{+}) (\sigma_{e_L^- e_R^+}+ \sigma_{e_R^- e_L^+})}
\label{ALR}
\eea
where the quantity $\sigma$ can be obtained by integrating over the scattering angle $\theta$ as 
\bea
\sigma \ = \  \int^{\cos\theta_{\rm{max}}}_{\cos\theta_{\rm{min}}} \frac{d\sigma}{d\cos\theta} d\cos\theta \, .
\eea
Due to $\frac{d\sigma_{e_L^- e_L^+}}{d\cos\theta}=\frac{d\sigma_{e_R^- e_R^+}}{d\cos\theta}$ we get $\sigma_{e_L^- e_L^+}=\sigma_{e_R^- e_R^+}$.

The deviation from the SM in the differential and integrated LR asymmetries can be written as
\bea
\Delta_{\mathcal{A}_{\rm{LR}}} (\cos\theta) \ = \  \frac{\mathcal{A}_{\rm{LR}}^{U(1)_X}(\cos\theta)}{\mathcal{A}_{\rm{LR}}^{\rm{SM}}(\cos\theta)}-1\, , \,\,\,




\Delta_{\mathcal{A}_{\rm{LR}}} \ = \ \frac{\mathcal{A}_{\rm{LR}}^{U(1)_X}}{\mathcal{A}_{\rm{LR}}^{\rm{SM}}}-1 \, ,
\label{LR-2}
\eea
respectively. The theoretically estimated statistical error can be estimated as  
\begin{align}
 \Delta \mathcal{A}_{LR} 






\  = \ \frac{2\sqrt{N_{1}N_{2}}}
 {(N_{1}+N_{2})
 \left(\sqrt{N_{1}}-\sqrt{N_{2}}\right)}
{\cal A}_{LR} \, ,
\label{Eq:Error-A_LR}
\end{align}
where $N_{1}=\mathcal{L}_{\rm int} \, \sigma(P_{e^-}=-P_-,P_{e^+}=-P_+)$ and $N_{2}=\mathcal{L}_{\rm int} \, \sigma(P_{e^-}=+P_-,P_{e^+}=+P_+)$. 


